"""Levels 7-15 lesson specs. rest_courses(lesson, q, course) -> list of courses."""

def rest_courses(lesson, q, course):
    def two(first, second):
        return [q(*first), q(*second)]

    def L(slug, es_t, en_t, es_d, en_d, es_why, en_why, es_c, en_c, es_cmd, en_cmd, es_p, en_p, first, second, warning=None):
        return lesson(
            slug, es_t, en_t, es_d, en_d, es_why, en_why, es_c, en_c,
            es_cmd, en_cmd, es_p, en_p, two(first, second), warning,
        )

